// ---------- helpers ----------
const STATUS = {
  D: { label: "DEFINIDO", fill: "2E7D32" },
  P: { label: "PROPUESTA", fill: "1F7FB0" },
  X: { label: "POR DEFINIR", fill: ORANGE }, // espacio duro: la etiqueta no se parte entre líneas
};
const tag = (s) => new TextRun({
  text: ` ${STATUS[s].label} `, bold: true, size: 15, color: "FFFFFF", font: FONT,
  shading: { type: ShadingType.CLEAR, color: "auto", fill: STATUS[s].fill },
});

// **negrita** en línea
function runs(text, opts = {}) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g).filter(Boolean);
  return parts.map((t) => t.startsWith("**")
    ? new TextRun({ text: t.slice(2, -2), bold: true, ...opts })
    : new TextRun({ text: t, ...opts }));
}

// La etiqueta de estado va en su propia línea bajo el título para que no aparezca en el índice
const tagLine = (s) => new Paragraph({ keepNext: true, spacing: { after: 100 }, children: [tag(s)] });
const h1 = (t, s, pageBreakBefore = false) => [new Paragraph({ heading: HeadingLevel.HEADING_1, pageBreakBefore, children: [new TextRun(t)] }), ...(s ? [tagLine(s)] : [])];
const h2 = (t, s) => [new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(t)] }), ...(s ? [tagLine(s)] : [])];
const p = (t, s, keepNext = false) => new Paragraph({
  spacing: { after: 120 }, keepNext,
  children: s ? [tag(s), new TextRun("  "), ...runs(t)] : runs(t),
});
const note = (t) => new Paragraph({ spacing: { after: 120 }, keepNext: true, children: runs(t, { italics: true, color: GREY }) });
const bullet = (t, s) => new Paragraph({
  numbering: { reference: "bullets", level: 0 }, spacing: { after: 60 },
  children: s ? [...runs(t), new TextRun("  "), tag(s)] : runs(t),
});
const num = (t, ref) => new Paragraph({ numbering: { reference: ref, level: 0 }, spacing: { after: 60 }, children: runs(t) });

const border = { style: BorderStyle.SINGLE, size: 6, color: "B8C4D0" };
const borders = { top: border, bottom: border, left: border, right: border };
const margins = { top: 80, bottom: 80, left: 120, right: 120 };

function cellContent(c, keepNext) {
  if (c && typeof c === "object" && c.tag) return [new Paragraph({ keepNext, children: [tag(c.tag)] })];
  return [new Paragraph({ keepNext, children: runs(String(c), { size: 20 }) })];
}

// keep = false deja que una tabla larga se parta entre páginas (la fila de encabezado se repite)
function table(widths, header, rows, keep = true) {
  const total = widths.reduce((a, b) => a + b, 0);
  const mk = (cells, isHead, isLast) => new TableRow({
    tableHeader: isHead, cantSplit: true,
    children: cells.map((c, i) => new TableCell({
      borders, margins, width: { size: widths[i], type: WidthType.DXA }, verticalAlign: VerticalAlign.CENTER,
      shading: { type: ShadingType.CLEAR, color: "auto", fill: isHead ? NAVY : (i === 0 ? LIGHT : "FFFFFF") },
      children: isHead
        ? [new Paragraph({ keepNext: true, children: [new TextRun({ text: c, bold: true, color: "FFFFFF", size: 20 })] })]
        : cellContent(c, keep && !isLast),
    })),
  });
  return new Table({
    width: { size: total, type: WidthType.DXA }, columnWidths: widths,
    rows: [mk(header, true, false), ...rows.map((r, i) => mk(r, false, i === rows.length - 1))],
  });
}
const gap = () => new Paragraph({ spacing: { after: 120 }, children: [] });
